'use strict';

// Lāčplēsis (Bearslayer).
// The map of Latvia is a set of small locations, a few per novads, opened one after another.

// ---------- Canvas ----------
const canvas = document.getElementById('game');
let ctx = canvas.getContext('2d');   // `let`: scenery sprites are drawn by pointing it at a small canvas for a moment
let VW = 0, VH = 0, DPR = 1, Z = 1;

function resize() {
  DPR = window.devicePixelRatio || 1;
  VW = window.innerWidth;
  VH = window.innerHeight;
  canvas.width = Math.floor(VW * DPR);
  canvas.height = Math.floor(VH * DPR);
  canvas.style.width = VW + 'px';
  canvas.style.height = VH + 'px';
  Z = clamp(Math.min(VW / 1100, VH / 750), 0.5, 1.2);
}

// ---------- Helpers ----------
const TAU = Math.PI * 2;
const FONT = '"Trebuchet MS", "Segoe UI", sans-serif';
const rand = (a, b) => a + Math.random() * (b - a);
const randi = (a, b) => Math.floor(rand(a, b + 1));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const angleDiff = (a, b) => ((a - b + Math.PI) % TAU + TAU) % TAU - Math.PI;
const lerp = (a, b, t) => a + (b - a) * t;
const dist = (ax, ay, bx, by) => Math.hypot(ax - bx, ay - by);
const pick = arr => arr[Math.floor(Math.random() * arr.length)];

function seeded(seed) {
  return function () {
    seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function weighted(list) {
  let total = 0;
  for (const it of list) total += it.w;
  let r = Math.random() * total;
  for (const it of list) { r -= it.w; if (r <= 0) return it; }
  return list[list.length - 1];
}

