// ---------- Location world ----------
const WORLD_W = 2600, WORLD_H = 1800;
const CELL = 25;
const GW = Math.ceil(WORLD_W / CELL), GH = Math.ceil(WORLD_H / CELL);
const T_SEA = 0, T_EDGE = 1, T_LAND = 2, T_WATER = 3, T_BRIDGE = 4, T_FOREST = 5, T_BUILD = 6;
const MZ = 6;   // labyrinth room size, in grid cells
const terrain = new Uint8Array(GW * GH);
const blocked = new Uint8Array(GW * GH);    // 0 free, 1 water (swim or fly), 2 hard, 3 forest (burn or fly)
const sandy = new Uint8Array(GW * GH);
const swamp = new Uint8Array(GW * GH);   // boggy ground by lakes and rivers: walkable, but slow
const reef = new Uint8Array(GW * GH);    // shallow water out at sea that can be swum, like Kolka's sēre
// Footprints of the big buildings (half-width, depth), which Lāčplēsis walks around.
const LANDMARKS = {
  castle: { w: 95, d: 34 }, ruins: { w: 95, d: 30 }, redcastle: { w: 70, d: 30 }, palace: { w: 175, d: 40 },
  lighthouse: { w: 26, d: 22 }, tower: { w: 30, d: 24 },
};

let L = null;   // the location being played: its layout, scenery and canvases
let ovCanvas, glowBlue, glowGold;

function pointInPoly(pts, x, y) {
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const a = pts[i], b = pts[j];
    if ((a.y > y) !== (b.y > y) && x < (b.x - a.x) * (y - a.y) / (b.y - a.y) + a.x) inside = !inside;
  }
  return inside;
}

function smoothLine(pts, steps) {
  const out = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(pts.length - 1, i + 2)];
    for (let s = 0; s < steps; s++) {
      const t = s / steps, t2 = t * t, t3 = t2 * t;
      const f = (a, b, c, d) => 0.5 * (2 * b + (-a + c) * t + (2 * a - 5 * b + 4 * c - d) * t2 + (-a + 3 * b - 3 * c + d) * t3);
      out.push({ x: f(p0.x, p1.x, p2.x, p3.x), y: f(p0.y, p1.y, p2.y, p3.y) });
    }
  }
  out.push(pts[pts.length - 1]);
  return out;
}

function segDist(px, py, a, b) {
  const dx = b.x - a.x, dy = b.y - a.y;
  const l2 = dx * dx + dy * dy;
  const t = l2 ? clamp(((px - a.x) * dx + (py - a.y) * dy) / l2, 0, 1) : 0;
  return Math.hypot(px - (a.x + dx * t), py - (a.y + dy * t));
}

function polyDist(pts, x, y) {
  let best = Infinity;
  for (let i = 0; i < pts.length - 1; i++) best = Math.min(best, segDist(x, y, pts[i], pts[i + 1]));
  return best;
}

const cellOf = (x, y) => {
  const cx = Math.floor(x / CELL), cy = Math.floor(y / CELL);
  if (cx < 0 || cy < 0 || cx >= GW || cy >= GH) return -1;
  return cy * GW + cx;
};

// mode: falsy = walking, 'swim' = may enter water, anything else truthy = flying.
function walkable(x, y, mode) {
  const i = cellOf(x, y);
  return i >= 0 && walkCell(i, mode);
}

// The map of Latvia for the map screen, drawn once into a canvas.
function buildOverview() {
  const pts = flat => { const out = []; for (let i = 0; i < flat.length; i += 2) out.push(P(flat[i], flat[i + 1])); return out; };
  ovCanvas = document.createElement('canvas');
  ovCanvas.width = Math.round(OV_W * OV_S); ovCanvas.height = Math.round(OV_H * OV_S);
  const c = ovCanvas.getContext('2d');
  c.setTransform(OV_S, 0, 0, OV_S, -OV_X0 * OV_S, -OV_Y0 * OV_S);
  const path = (p, close) => { c.beginPath(); c.moveTo(p[0].x, p[0].y); for (let i = 1; i < p.length; i++) c.lineTo(p[i].x, p[i].y); if (close) c.closePath(); };
  const text = (p, s, size, color) => {
    c.font = `900 ${size}px ${FONT}`; c.textAlign = 'center'; c.textBaseline = 'middle';
    c.fillStyle = color; c.fillText(s, p.x, p.y);
  };
  const LV = pts(LV_LL);
  c.lineJoin = 'round'; c.lineCap = 'round';
  c.fillStyle = '#5f9fd3'; c.fillRect(OV_X0, OV_Y0, OV_W, OV_H);
  // a sandy beach along the coast: the land drawn on top hides it everywhere else
  path(LV, true); c.strokeStyle = '#eadcaa'; c.lineWidth = 18; c.stroke();
  for (const r of NEIGH_LL) {
    path(pts(r), true); c.fillStyle = '#cfc8a8'; c.fill();
    c.strokeStyle = '#eadcaa'; c.lineWidth = 6; c.stroke();
  }
  for (const [name, lon, lat] of [['IGAUNIJA', 25.9, 58.2], ['KRIEVIJA', 28.45, 56.95], ['BALTKRIEVIJA', 27.6, 55.62],
    ['LIETUVA', 23.6, 55.85]]) text(P(lon, lat), name, 90, 'rgba(120,108,80,0.4)');
  text(P(20.62, 56.85), 'Baltijas', 70, 'rgba(255,255,255,0.5)');
  text(P(20.62, 56.72), 'jūra', 70, 'rgba(255,255,255,0.5)');
  text(P(23.6, 57.62), 'Rīgas jūras līcis', 70, 'rgba(255,255,255,0.5)');
  // region colours from the grid, stretched smooth and clipped to Latvia
  const G = REGION_GRID, rows = G.rows.length;
  const rc = document.createElement('canvas');
  rc.width = G.cols; rc.height = rows;
  const rctx = rc.getContext('2d'), img = rctx.createImageData(G.cols, rows);
  G.rows.forEach((row, y) => {
    let x = 0;
    for (const [, n, ch] of row.matchAll(/(\d*)([.a-f])/g)) {
      const col = ch === '.' ? [207, 200, 168] : REGIONS[ch.charCodeAt(0) - 97].color;
      for (let k = 0; k < (n ? +n : 1); k++, x++) img.data.set([col[0], col[1], col[2], 255], (y * G.cols + x) * 4);
    }
  });
  rctx.putImageData(img, 0, 0);
  const g0 = P(G.lon0, G.lat0), g1 = P(G.lon0 + G.cols * G.dlon, G.lat0 - rows * G.dlat);
  c.save();
  path(LV, true); c.clip();
  c.imageSmoothingEnabled = true;
  c.drawImage(rc, g0.x, g0.y, g1.x - g0.x, g1.y - g0.y);
  c.restore();
  path(LV, true); c.strokeStyle = 'rgba(90,70,40,0.45)'; c.lineWidth = 4; c.stroke();
  for (const r of BORDER_LL) { path(pts(r)); c.strokeStyle = 'rgba(120,80,40,0.6)'; c.lineWidth = 8; c.setLineDash([30, 20]); c.stroke(); }
  c.setLineDash([]);
  for (const l of LAKES_LL) {
    const p = pts(l);
    path(p, true); c.strokeStyle = '#3d7fb8'; c.lineWidth = 8; c.stroke();
    c.fillStyle = '#5aa3e0'; c.fill();
  }
  for (const r of RIVERS_LL) {
    const p = smoothLine(pts(r.pts), 4);
    path(p); c.strokeStyle = '#3d7fb8'; c.lineWidth = r.w * 2 + 8; c.stroke();
    path(p); c.strokeStyle = '#5aa3e0'; c.lineWidth = r.w * 2; c.stroke();
  }
  for (const R of REGIONS) if (R !== REGIONS[RIG]) text(P(...R.label), R.name.toUpperCase(), 130, 'rgba(255,255,255,0.3)');

  glowBlue = makeGlow('80,180,255');
  glowGold = makeGlow('255,205,60');
}

// Build the playing area of one location. The layout is fixed every game, so it can be learned.
function buildLocation(def) {
  const rng = seeded(def.seed);
  const R = REGIONS[def.region];
  const N = p => ({ x: p[0] * WORLD_W, y: p[1] * WORLD_H });
  const l = {
    def, R, start: N(def.start), spring: def.spring ? N(def.spring) : null, paija: def.paija ? N(def.paija) : null,
    boss: def.boss ? { ...def.boss, ...N(def.boss.at) } : null,
    houses: (def.houses || []).map(([id, p]) => ({ id, ...N(p) })),
    landmark: def.landmark ? { type: def.landmark[0], ...N(def.landmark[1]) } : null,
    rivers: [], bridges: [], falls: null, lakes: [], decor: [], waves: [], village: null, landCells: [],
  };
  l.sign = { x: l.start.x - 85, y: l.start.y + 20 };
  l.bossR = !l.boss ? 0 : l.boss.type === 'jods' ? 210 + (l.boss.heads || 3) * 14 : lairForest(def) >= 0 ? LAIR_R : 200;
  const seas = (def.sea || []).map(poly => poly.map(N));
  // `river` is one river, or a list of them (a main river and a smaller one flowing into it)
  for (const r of [].concat(def.river || [])) {
    const pts = smoothLine(r.pts.map(N), 12);
    const xs = pts.map(p => p.x), ys = pts.map(p => p.y);
    l.rivers.push({ w: r.w, pts, name: r.name, x0: Math.min(...xs), x1: Math.max(...xs), y0: Math.min(...ys), y1: Math.max(...ys) });
    const along = t => {
      const i = clamp(Math.round(t * (pts.length - 1)), 0, pts.length - 2);
      const a = pts[i], c = pts[i + 1], len = Math.hypot(c.x - a.x, c.y - a.y) || 1;
      const dx = (c.x - a.x) / len, dy = (c.y - a.y) / len;
      return { x: a.x, y: a.y, dx, dy, px: -dy, py: dx };
    };
    for (const b of r.bridges || []) l.bridges.push({ ...along(b.t), half: r.w + 95, water: r.w + 12, wide: b.big ? 72 : 58, big: !!b.big, brick: !!b.brick });
    if (r.falls !== undefined) l.falls = { ...along(r.falls), w: r.w };
  }
  // a lake is [x, y, rx, ry, turn (radians, optional), name (optional)]
  l.lakes = (def.lakes || []).map(([x, y, rx, ry, a = 0, name]) => ({ ...N([x, y]), rx, ry, a, name }));

  for (let cy = 0; cy < GH; cy++) {
    for (let cx = 0; cx < GW; cx++) {
      const i = cy * GW + cx, x = (cx + 0.5) * CELL, y = (cy + 0.5) * CELL;
      sandy[i] = 0; swamp[i] = 0; reef[i] = 0;
      let t = T_LAND;
      if (seas.some(s => pointInPoly(s, x, y))) t = T_SEA;
      else {
        for (const r of l.rivers) {
          const m = r.w + 12;
          if (x > r.x0 - m && x < r.x1 + m && y > r.y0 - m && y < r.y1 + m && polyDist(r.pts, x, y) < m) t = T_WATER;
        }
        for (const k of l.lakes) {
          const dx = x - k.x, dy = y - k.y, cs = Math.cos(k.a), sn = Math.sin(k.a);
          const u = (dx * cs + dy * sn) / (k.rx + 10), v = (-dx * sn + dy * cs) / (k.ry + 10);
          if (u * u + v * v < 1) t = T_WATER;
        }
        for (const b of l.bridges) {
          const u = (x - b.x) * b.dx + (y - b.y) * b.dy, v = (x - b.x) * b.px + (y - b.y) * b.py;
          if (Math.abs(u) < b.wide && Math.abs(v) < b.half) t = T_BRIDGE;
        }
      }
      if (t === T_LAND) {
        // a thick, ragged belt of forest round the edge of the location
        const e = Math.min(cx, cy, GW - 1 - cx, GH - 1 - cy);
        const th = 2.2 + (Math.sin(cx * 0.7 + cy * 0.3) + Math.sin(cx * 0.23 - cy * 0.51 + 1)) * 0.6;
        if (e < th) t = T_EDGE;
      }
      terrain[i] = t;
    }
  }
  // sandy beaches along the sea
  if (seas.length) {
    for (let i = 0; i < GW * GH; i++) {
      if (terrain[i] !== T_LAND && terrain[i] !== T_EDGE) continue;
      const cx = i % GW, cy = Math.floor(i / GW);
      for (let dy = -3; dy <= 3 && !sandy[i]; dy++) {
        for (let dx = -3; dx <= 3; dx++) {
          const x = cx + dx, y = cy + dy;
          if (x >= 0 && y >= 0 && x < GW && y < GH && terrain[y * GW + x] === T_SEA && dx * dx + dy * dy <= 10) { sandy[i] = 1; break; }
        }
      }
      if (sandy[i] && terrain[i] === T_EDGE && Math.min(cx, cy, GW - 1 - cx, GH - 1 - cy) > 0) terrain[i] = T_LAND;
    }
  }

  buildIslands(def, l, N);

  // places that get an open clearing
  const clear = [[l.start.x, l.start.y, 170], [l.sign.x, l.sign.y, 70]];
  if (l.spring) clear.push([l.spring.x, l.spring.y, 140]);
  if (l.boss) clear.push([l.boss.x, l.boss.y - 30, l.bossR]);
  for (const hs of l.houses) clear.push([hs.x, hs.y, 140]);
  if (l.paija) clear.push([l.paija.x, l.paija.y, 110]);
  if (l.landmark) clear.push([l.landmark.x, l.landmark.y - 20, LANDMARKS[l.landmark.type].w + 80]);
  if (def.village) {
    const p = N(def.village), houses = [];
    for (let k = 0, n = 4 + Math.floor(rng() * 2); k < n; k++) {
      const a = rng() * TAU, r = 44 * Math.sqrt(rng());
      houses.push({ x: Math.cos(a) * r, y: Math.sin(a) * r * 0.7, s: 0.85 + rng() * 0.35 });
    }
    houses.sort((a, b) => a.y - b.y);
    l.village = { ...p, houses };
    clear.push([p.x, p.y, 130]);
  }
  for (const b of l.bridges) for (const s of [-1, 1]) clear.push([b.x + b.px * s * (b.half + 30), b.y + b.py * s * (b.half + 30), 110]);

  buildForests(def, rng);
  // small copses of trees out on the meadows
  for (let k = 0, tries = 0; k < (def.copses ?? 12) && tries < 500; tries++) {
    const cx = 4 + Math.floor(rng() * (GW - 8)), cy = 4 + Math.floor(rng() * (GH - 8));
    const i = cy * GW + cx;
    if (terrain[i] !== T_LAND || sandy[i]) continue;
    const x = (cx + 0.5) * CELL, y = (cy + 0.5) * CELL;
    if (clear.some(([a, b, r]) => dist(x, y, a, b) < r + 40)) continue;
    let nearWater = false;
    for (let dy = -3; dy <= 3; dy++) for (let dx = -3; dx <= 3; dx++) {
      const t = terrain[(cy + dy) * GW + cx + dx];
      if (t === T_WATER || t === T_BRIDGE || t === T_SEA || t === T_FOREST) nearWater = true;
    }
    if (nearWater) continue;
    const rad = 0.8 + rng() * 1.1;
    for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) {
      const j = (cy + dy) * GW + cx + dx;
      if (Math.hypot(dx, dy) <= rad && terrain[j] === T_LAND) terrain[j] = T_FOREST;
    }
    k++;
  }
  // laid-out swamp areas (the klāni at Lubāns): round bogs with ragged edges and no trees in them
  l.swampAreas = (def.swampAreas || []).map(([x, y, rx, ry], k) => ({ ...N([x, y]), rx, ry, ph: k * 1.7 }));
  for (let i = 0; i < GW * GH; i++) {
    if (terrain[i] === T_FOREST && inSwampArea(l, (i % GW + 0.5) * CELL, (Math.floor(i / GW) + 0.5) * CELL, 1.1)) terrain[i] = T_LAND;
  }
  for (const [x, y, r] of clear) {
    for (let cy = Math.max(0, Math.floor((y - r) / CELL)); cy <= Math.min(GH - 1, Math.floor((y + r) / CELL)); cy++) {
      for (let cx = Math.max(0, Math.floor((x - r) / CELL)); cx <= Math.min(GW - 1, Math.floor((x + r) / CELL)); cx++) {
        const i = cy * GW + cx;
        if (terrain[i] === T_FOREST && dist((cx + 0.5) * CELL, (cy + 0.5) * CELL, x, y) < r) terrain[i] = T_LAND;
      }
    }
  }
  if (l.landmark) {
    const lm = l.landmark, F = LANDMARKS[lm.type];
    for (let cy = Math.floor((lm.y - F.d) / CELL); cy <= Math.floor((lm.y + 4) / CELL); cy++) {
      for (let cx = Math.floor((lm.x - F.w) / CELL); cx <= Math.floor((lm.x + F.w) / CELL); cx++) {
        if (cx >= 0 && cy >= 0 && cx < GW && cy < GH && terrain[cy * GW + cx] === T_LAND) terrain[cy * GW + cx] = T_BUILD;
      }
    }
  }
  fixConnectivity(rng, l.start);

  // the open ground that can be reached from the start, for placing things
  const reach = reachable(l.start);
  for (let i = 0; i < GW * GH; i++) if (reach[i] && terrain[i] === T_LAND) l.landCells.push(i);
  l.reach = reach;

  // big crop fields out on the meadows (walkable, just drawn on the ground)
  l.fields = [];
  for (let k = 0, tries = 0; k < (def.fields ?? R.fields ?? 0) && tries < 300; tries++) {
    const w = 260 + rng() * 160, h = 160 + rng() * 90, a = (rng() - 0.5) * 0.5;
    const x = 120 + rng() * (WORLD_W - 240), y = 120 + rng() * (WORLD_H - 240);
    const cs = Math.cos(a), sn = Math.sin(a);
    let ok = true;
    for (let u = -1; u <= 1 && ok; u += 0.25) for (let v = -1; v <= 1 && ok; v += 0.25) {
      const px = x + (u * w / 2 + 25 * Math.sign(u)) * cs - (v * h / 2 + 25 * Math.sign(v)) * sn;
      const py = y + (u * w / 2 + 25 * Math.sign(u)) * sn + (v * h / 2 + 25 * Math.sign(v)) * cs;
      const i = cellOf(px, py);
      if (i < 0 || terrain[i] !== T_LAND || sandy[i]) ok = false;
    }
    if (!ok || clear.some(([kx, ky, kr]) => dist(x, y, kx, ky) < kr + Math.max(w, h) * 0.4)) continue;
    if (l.swampAreas.some(a => dist(x, y, a.x, a.y) < Math.max(a.rx, a.ry) * 1.15 + Math.max(w, h) * 0.6)) continue;
    if (l.fields.some(f => dist(x, y, f.x, f.y) < (Math.max(w, h) + Math.max(f.w, f.h)) * 0.6)) continue;
    l.fields.push({ x, y, w, h, a, crop: (def.crops || R.crops)[Math.floor(rng() * (def.crops || R.crops).length)],
      hay: rng() < 0.6 ? 1 + Math.floor(rng() * 3) : 0, v: rng() });
    k++;
  }
  const inField = (x, y) => l.fields.some(f => {
    const dx = x - f.x, dy = y - f.y, cs = Math.cos(f.a), sn = Math.sin(f.a);
    return Math.abs(dx * cs + dy * sn) < f.w / 2 + 15 && Math.abs(-dx * sn + dy * cs) < f.h / 2 + 15;
  });

  buildSwamps(def, l, clear, inField);
  l.swampCells = l.landCells.filter(i => swamp[i]);

  // scenery
  // by the sea the forests are pine forests
  const coastal = !!(def.sea && def.sea.length);
  const trees = def.trees || (coastal ? COAST_TREES : R.trees);
  const open = R.open || [['flowers', 1]];
  let openTotal = 0;
  for (const d of open) openTotal += d[1];
  for (let i = 0; i < GW * GH; i++) {
    const t = terrain[i], cx = i % GW, cy = Math.floor(i / GW);
    if (t === T_FOREST || t === T_EDGE) {
      const list = t === T_EDGE ? (coastal ? COAST_TREES : R.trees) : trees;
      const type = sandy[i] ? 'pine' : list[Math.floor(rng() * list.length)];
      l.decor.push({ cell: t === T_FOREST ? i : undefined, type, x: (cx + 0.5) * CELL + (rng() - 0.5) * 10,
        y: (cy + 0.5) * CELL + (rng() - 0.5) * 10, s: (t === T_EDGE ? 1.15 : 1.0) + rng() * 0.3, v: rng() });
      continue;
    }
    if (t !== T_LAND || rng() > 0.06) continue;
    const x = (cx + 0.5) * CELL + (rng() - 0.5) * 20, y = (cy + 0.5) * CELL + (rng() - 0.5) * 20;
    if (clear.some(([kx, ky, kr]) => dist(x, y, kx, ky) < kr * 0.6) || inField(x, y)) continue;
    let type = 'rock';
    if (!sandy[i]) {
      let r = rng() * openTotal;
      for (const d of open) { r -= d[1]; if (r <= 0) { type = d[0]; break; } }
    }
    const d = { type, x, y, s: 0.8 + rng() * 0.45, v: rng() };
    if (!swamp[i]) l.decor.push(d);
  }
  l.decor.sort((a, b) => a.y - b.y);
  for (let k = 0; k < 400; k++) {
    const x = rng() * WORLD_W, y = rng() * WORLD_H, i = cellOf(x, y);
    if (i >= 0 && terrain[i] === T_SEA) l.waves.push({ x, y, s: 0.7 + rng() * 0.6 });
  }

  // ground colours, drawn at grid resolution and stretched so they blend softly
  l.groundCanvas = document.createElement('canvas');
  l.groundCanvas.width = GW; l.groundCanvas.height = GH;
  const gctx = l.groundCanvas.getContext('2d'), img = gctx.createImageData(GW, GH);
  for (let i = 0; i < GW * GH; i++) {
    const t = terrain[i], cx = i % GW, cy = Math.floor(i / GW);
    let c = R.color, f = 1 + 0.07 * Math.sin(cx * 0.19 + def.seed) * Math.cos(cy * 0.23);
    if (def.hill) {
      // a big hill: the ground gets lighter towards the top, in soft rings
      const [hx, hy, hr] = def.hill, d = Math.hypot((cx + 0.5) * CELL - hx * WORLD_W, ((cy + 0.5) * CELL - hy * WORLD_H) * 1.3) / (hr * WORLD_W);
      if (d < 1) f *= 1 + 0.3 * (1 - d) + 0.05 * Math.cos(d * 22) * (1 - d);
    }
    if (t === T_SEA) { c = [95, 159, 211]; f = 1; }
    else if (reef[i]) { c = [128, 196, 214]; f = 1; }
    else if (swamp[i]) { c = [118, 124, 70]; f = 0.95 + 0.08 * Math.sin(cx * 0.9 + cy * 0.7); }
    else if (t === T_WATER) { c = [90, 150, 205]; f = 1; }
    else if (sandy[i]) { c = [232, 214, 160]; f = 1; }
    if (t === T_FOREST || t === T_EDGE) f *= 0.62;
    const n = (rng() - 0.5) * 12;
    img.data[i * 4] = clamp(c[0] * f + n, 0, 255);
    img.data[i * 4 + 1] = clamp(c[1] * f + n, 0, 255);
    img.data[i * 4 + 2] = clamp(c[2] * f + n * 0.6, 0, 255);
    img.data[i * 4 + 3] = 255;
  }
  gctx.putImageData(img, 0, 0);
  L = l;
}

// Islands in lakes or the sea, and shallow reefs out to them. An island can only be reached by
// swimming (or the broom), so it's a good place for a few valuable gifts (`gifts`), which come
// back a while after they're taken. An island is [x, y, rx, ry, { gifts, trees }]; a reef is
// [from, to, half-width] and turns sea into swimmable shallow water.
const ISLAND_REGROW = 90;   // seconds until a taken island gift is back
function buildIslands(def, l, N) {
  const rng = seeded(def.seed + 571);
  l.islands = (def.islands || []).map(([x, y, rx, ry, opt = {}]) => ({ ...N([x, y]), rx, ry, gifts: opt.gifts || [], trees: opt.trees || 0 }));
  l.islandGifts = [];
  for (const [a, b, w] of def.reefs || []) {
    const pa = N(a), pb = N(b);
    for (let i = 0; i < GW * GH; i++) {
      if (terrain[i] !== T_SEA) continue;
      if (segDist((i % GW + 0.5) * CELL, (Math.floor(i / GW) + 0.5) * CELL, pa, pb) < w) { terrain[i] = T_WATER; reef[i] = 1; }
    }
  }
  for (const is of l.islands) {
    for (let i = 0; i < GW * GH; i++) {
      const u = ((i % GW + 0.5) * CELL - is.x) / is.rx, v = ((Math.floor(i / GW) + 0.5) * CELL - is.y) / is.ry;
      const r = Math.hypot(u, v);
      if (r < 1) { terrain[i] = T_LAND; sandy[i] = r > 0.62 ? 1 : 0; reef[i] = 0; }
    }
    // gifts in a ring round the middle (where a lighthouse may stand)
    is.gifts.forEach((id, k) => {
      const a = -Math.PI / 2 + (k + 0.5) / is.gifts.length * TAU;
      l.islandGifts.push({ id, x: is.x + Math.cos(a) * is.rx * 0.5, y: is.y + Math.sin(a) * is.ry * 0.5 + 10 });
    });
    for (let k = 0; k < is.trees; k++) {
      const a = rng() * TAU, r = 0.25 + rng() * 0.3;
      l.decor.push({ type: rng() < 0.5 ? 'pine' : 'birch', x: is.x + Math.cos(a) * is.rx * r, y: is.y + Math.sin(a) * is.ry * r,
        s: 0.9 + rng() * 0.3, v: rng() });
    }
  }
}

// Swamps (purvi) on the meadows beside lakes and rivers, never near the sea: a few soft blobs of
// boggy ground with reeds and puddles. They have their own random numbers, so adding them left
// every other part of the layouts as it was.
const SWAMP_SLOW = 0.5;   // walking speed in a swamp
// Inside one of a place's laid-out swamp areas: an oval with a gently wobbling edge.
function inSwampArea(l, x, y, grow = 1) {
  return l.swampAreas.some(a => {
    const u = (x - a.x) / a.rx, v = (y - a.y) / a.ry, th = Math.atan2(v, u);
    return Math.hypot(u, v) < grow * (1 + 0.1 * Math.sin(3 * th + a.ph) + 0.05 * Math.sin(5 * th + a.ph * 2));
  });
}

function buildSwamps(def, l, clear, inField) {
  const rng = seeded(def.seed + 313);
  // spots kept dry (landings for a swim across), as [x, y, radius] in fractions and pixels
  const dry = (def.dry || []).map(([x, y, r]) => ({ x: x * WORLD_W, y: y * WORLD_H, r }));
  const isDry = (x, y) => dry.some(d => dist(x, y, d.x, d.y) < d.r);
  const n = def.swamps ?? (l.lakes.length || l.rivers.length ? (def.region === LAT ? 4 : 2) : 0);
  for (let i = 0; i < GW * GH; i++) {
    if (!l.swampAreas.length) break;
    if (terrain[i] !== T_LAND || sandy[i]) continue;
    const x = (i % GW + 0.5) * CELL, y = (Math.floor(i / GW) + 0.5) * CELL;
    if (dist(x, y, l.start.x, l.start.y) < 200 || isDry(x, y)) continue;
    if (inSwampArea(l, x, y)) swamp[i] = 1;
  }
  if (!n) return;
  const near = (i, r, test) => {
    const cx = i % GW, cy = Math.floor(i / GW);
    for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
      const x = cx + dx, y = cy + dy;
      if (x >= 0 && y >= 0 && x < GW && y < GH && dx * dx + dy * dy <= r * r && test(terrain[y * GW + x])) return true;
    }
    return false;
  };
  const ok = i => {
    if (terrain[i] !== T_LAND || sandy[i]) return false;
    const x = (i % GW + 0.5) * CELL, y = (Math.floor(i / GW) + 0.5) * CELL;
    if (isDry(x, y)) return false;
    return !inField(x, y) && !clear.some(([a, b, r]) => dist(x, y, a, b) < r + 30);
  };
  const seeds = [];
  for (let tries = 0; tries < 800 && seeds.length < n; tries++) {
    const i = Math.floor(rng() * GW * GH);
    if (!ok(i) || !near(i, 3, t => t === T_WATER) || near(i, 12, t => t === T_SEA)) continue;
    if (seeds.some(j => Math.hypot(j % GW - i % GW, Math.floor(j / GW) - Math.floor(i / GW)) < 16)) continue;
    seeds.push(i);
  }
  for (const i of seeds) {
    const cx = i % GW, cy = Math.floor(i / GW), rx = 4 + rng() * 3, ry = 3 + rng() * 2.5, ph = rng() * TAU;
    for (let dy = -8; dy <= 8; dy++) for (let dx = -10; dx <= 10; dx++) {
      const x = cx + dx, y = cy + dy;
      if (x < 0 || y < 0 || x >= GW || y >= GH) continue;
      const j = y * GW + x, th = Math.atan2(dy, dx);
      const r = Math.hypot(dx / rx, dy / ry) / (1 + 0.2 * Math.sin(3 * th + ph));
      if (r < 1 && ok(j) && !near(j, 9, t => t === T_SEA)) swamp[j] = 1;
    }
  }
  // reeds, grass tussocks and dark puddles
  for (let i = 0; i < GW * GH; i++) {
    if (!swamp[i] || rng() > 0.45) continue;
    const r = rng(), type = r < 0.4 ? 'reeds' : r < 0.75 ? 'puddle' : 'tussock';
    l.decor.push({ type, x: (i % GW + 0.5) * CELL + (rng() - 0.5) * 18, y: (Math.floor(i / GW) + 0.5) * CELL + (rng() - 0.5) * 18,
      s: 0.8 + rng() * 0.5, v: rng() });
  }
}

// Plant each forest area and carve a small labyrinth into it over rooms of MZ×MZ cells, with a few
// ways in from the meadows.
function buildForests(def, rng) {
  const mask = new Int8Array(GW * GH).fill(-1);
  (def.forests || []).forEach(([fx, fy, frx, fry], k) => {
    const ph = rng() * TAU, ph2 = rng() * TAU;
    const x0 = fx * WORLD_W, y0 = fy * WORLD_H, rx = frx * WORLD_W, ry = fry * WORLD_H;
    for (let cy = 0; cy < GH; cy++) {
      for (let cx = 0; cx < GW; cx++) {
        const i = cy * GW + cx;
        if (terrain[i] !== T_LAND) continue;
        const u = ((cx + 0.5) * CELL - x0) / rx, v = ((cy + 0.5) * CELL - y0) / ry;
        const th = Math.atan2(v, u);
        if (Math.hypot(u, v) < 1 + 0.12 * Math.sin(3 * th + ph) + 0.07 * Math.sin(5 * th + ph2)) mask[i] = k;
      }
    }
  });
  // A forest with the boss at its centre is his lair: no extra loops, and only two ways in, as far
  // along the maze from his clearing as they can be, so reaching him means finding the way through.
  const lair = k => k === lairForest(def);
  const MW = Math.floor(GW / MZ), MH = Math.floor(GH / MZ);
  const nreg = new Int16Array(MW * MH).fill(-1);
  for (let my = 0; my < MH; my++) {
    for (let mx = 0; mx < MW; mx++) nreg[my * MW + mx] = mask[(my * MZ + 3) * GW + mx * MZ + 3];
  }
  const openE = new Uint8Array(MW * MH), openS = new Uint8Array(MW * MH), seen = new Uint8Array(MW * MH);
  const neighbours = n => {
    const mx = n % MW, my = Math.floor(n / MW), out = [];
    if (mx + 1 < MW) out.push([n + 1, openE, n]);
    if (mx > 0) out.push([n - 1, openE, n - 1]);
    if (my + 1 < MH) out.push([n + MW, openS, n]);
    if (my > 0) out.push([n - MW, openS, n - MW]);
    return out;
  };
  for (let s = 0; s < MW * MH; s++) {
    if (nreg[s] < 0 || seen[s]) continue;
    const stack = [s];
    seen[s] = 1;
    while (stack.length) {
      const cur = stack[stack.length - 1];
      const opts = neighbours(cur).filter(([m]) => !seen[m] && nreg[m] === nreg[cur]);
      if (!opts.length) { stack.pop(); continue; }
      const [m, arr, owner] = opts[Math.floor(rng() * opts.length)];
      arr[owner] = 1;
      seen[m] = 1;
      stack.push(m);
    }
  }
  // Knock out some extra walls, so there are loops and fewer long dead ends.
  for (let n = 0; n < MW * MH; n++) {
    if (nreg[n] < 0 || lair(nreg[n])) continue;
    const mx = n % MW, my = Math.floor(n / MW);
    if (mx + 1 < MW && nreg[n + 1] === nreg[n] && rng() < 0.15) openE[n] = 1;
    if (my + 1 < MH && nreg[n + MW] === nreg[n] && rng() < 0.15) openS[n] = 1;
  }
  for (let i = 0; i < GW * GH; i++) if (mask[i] >= 0) terrain[i] = T_FOREST;
  // The forest's ragged outline leaves gaps in the outer rooms' walls; a lair gets whole rooms of
  // trees, so its doors are the only ways in.
  for (let n = 0; n < MW * MH; n++) {
    if (nreg[n] < 0 || !lair(nreg[n])) continue;
    const mx = n % MW, my = Math.floor(n / MW);
    for (let oy = 0; oy < MZ; oy++) for (let ox = 0; ox < MZ; ox++) {
      const i = (my * MZ + oy) * GW + mx * MZ + ox;
      if (terrain[i] === T_LAND) terrain[i] = T_FOREST;
    }
  }
  const carve = (cx, cy) => {
    if (cx < 0 || cy < 0 || cx >= GW || cy >= GH) return;
    const i = cy * GW + cx;
    if (terrain[i] === T_FOREST) terrain[i] = T_LAND;
  };
  // carve a corridor 4 cells wide from room n's interior through k cells in direction (dx, dy)
  const corridor = (n, dx, dy, k) => {
    const mx = n % MW, my = Math.floor(n / MW);
    for (let s = 0; s < k; s++) {
      for (let w = 1; w <= MZ - 2; w++) {
        const cx = dx ? (dx > 0 ? (mx + 1) * MZ - 1 + s : mx * MZ - s) : mx * MZ + w;
        const cy = dy ? (dy > 0 ? (my + 1) * MZ - 1 + s : my * MZ - s) : my * MZ + w;
        carve(cx, cy);
      }
    }
  };
  const doors = {};
  for (let n = 0; n < MW * MH; n++) {
    if (nreg[n] < 0) continue;
    const mx = n % MW, my = Math.floor(n / MW);
    for (let oy = 1; oy <= MZ - 2; oy++) for (let ox = 1; ox <= MZ - 2; ox++) carve(mx * MZ + ox, my * MZ + oy);
    if (openE[n]) corridor(n, 1, 0, 2);
    if (openS[n]) corridor(n, 0, 1, 2);
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const x = mx + dx, y = my + dy;
      if (x < 1 || y < 1 || x >= MW - 1 || y >= MH - 1) continue;
      if (nreg[y * MW + x] !== nreg[n]) (doors[nreg[n]] = doors[nreg[n]] || []).push([n, dx, dy]);
    }
  }
  for (const k in doors) {
    let list = doors[k];
    for (let j = list.length - 1; j > 0; j--) { const r = Math.floor(rng() * (j + 1)); [list[j], list[r]] = [list[r], list[j]]; }
    if (lair(+k)) list = lairDoors(list, mazeDistFromBoss(def, MW, MH, openE, openS, nreg, +k), MW);
    const n = lair(+k) ? 2 : Math.max(2, Math.round(list.length * 0.2));
    for (const [room, dx, dy] of list.slice(0, n)) corridor(room, dx, dy, MZ + 2);
  }
}

// Which forest (index) has the boss at its centre, or -1.
function lairForest(def) {
  const at = def.boss && def.boss.at;
  if (!at) return -1;
  return (def.forests || []).findIndex(([fx, fy]) => (fx - at[0]) ** 2 + (fy - at[1]) ** 2 < 0.0004);
}
const LAIR_R = 140;   // the boss's clearing inside his lair, smaller than an open-air one

// Steps along the maze (in rooms) from the boss's clearing to every room of forest k.
function mazeDistFromBoss(def, MW, MH, openE, openS, nreg, k) {
  const bx = def.boss.at[0] * WORLD_W, by = def.boss.at[1] * WORLD_H, R = MZ * CELL;
  const d = new Int32Array(MW * MH).fill(-1), q = [];
  for (let n = 0; n < MW * MH; n++) {
    if (nreg[n] === k && dist(((n % MW) + 0.5) * R, (Math.floor(n / MW) + 0.5) * R, bx, by) < LAIR_R + R * 0.5) { d[n] = 0; q.push(n); }
  }
  for (let h = 0; h < q.length; h++) {
    const n = q[h], mx = n % MW;
    const links = [[mx + 1 < MW && openE[n], n + 1], [mx > 0 && openE[n - 1], n - 1], [openS[n], n + MW], [n >= MW && openS[n - MW], n - MW]];
    for (const [ok, m] of links) if (ok && m >= 0 && m < MW * MH && d[m] < 0 && nreg[m] === k) { d[m] = d[n] + 1; q.push(m); }
  }
  return d;
}

// The lair's two doors: the one farthest along the maze from the boss, then the farthest one that
// isn't right beside it.
function lairDoors(list, d, MW) {
  const sorted = [...list].sort((a, b) => d[b[0]] - d[a[0]]);
  const first = sorted[0];
  const apart = ([n]) => Math.abs(n % MW - first[0] % MW) + Math.abs(Math.floor(n / MW) - Math.floor(first[0] / MW)) >= 3;
  const second = sorted.slice(1).find(apart) || sorted[1];
  return [first, second, ...sorted.filter(x => x !== first && x !== second)];
}

// Every cell that can be walked to from p (over land and bridges).
function reachable(p) {
  const NC = GW * GH, reach = new Uint8Array(NC), q = new Int32Array(NC);
  const passable = i => terrain[i] === T_LAND || terrain[i] === T_BRIDGE;
  const s0 = cellOf(p.x, p.y);
  let qh = 0, qt = 0;
  q[qt++] = s0; reach[s0] = 1;
  while (qh < qt) {
    const c = q[qh++], cx = c % GW, cy = Math.floor(c / GW);
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const x = cx + dx, y = cy + dy;
      if (x < 0 || y < 0 || x >= GW || y >= GH) continue;
      const n = y * GW + x;
      if (!reach[n] && passable(n)) { reach[n] = 1; q[qt++] = n; }
    }
  }
  return reach;
}

// Rivers and copses can seal pockets off. Open gaps until every pocket that forest alone cuts
// off can be reached from the start.
function fixConnectivity(rng, start) {
  const NC = GW * GH;
  const passable = i => terrain[i] === T_LAND || terrain[i] === T_BRIDGE;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  for (let iter = 0; iter < 300; iter++) {
    const reach = reachable(start);
    const cands = [];
    for (let i = 0; i < NC; i++) {
      if (terrain[i] !== T_FOREST) continue;
      const cx = i % GW, cy = Math.floor(i / GW);
      for (const [dx, dy] of dirs) {
        const bx = cx - dx, by = cy - dy;
        if (bx < 0 || by < 0 || bx >= GW || by >= GH || !reach[by * GW + bx]) continue;
        for (let k = 1; k <= 3; k++) {
          const x = cx + dx * k, y = cy + dy * k;
          if (x < 0 || y < 0 || x >= GW || y >= GH) break;
          const j = y * GW + x;
          if (terrain[j] === T_FOREST) continue;
          if (passable(j) && !reach[j]) cands.push([cx, cy, dx, dy, k]);
          break;
        }
      }
    }
    if (!cands.length) break;
    const done = [];
    for (let tries = 0; tries < 40 && done.length < 6; tries++) {
      const c = cands[Math.floor(rng() * cands.length)];
      if (done.some(d => Math.abs(d[0] - c[0]) + Math.abs(d[1] - c[1]) < 16)) continue;
      done.push(c);
      const [cx, cy, dx, dy, k] = c;
      for (let m = 0; m < k; m++) {
        for (let w = -1; w <= 1; w++) {
          const x = cx + dx * m + (dy ? w : 0), y = cy + dy * m + (dx ? w : 0);
          if (x >= 0 && y >= 0 && x < GW && y < GH && terrain[y * GW + x] === T_FOREST) terrain[y * GW + x] = T_LAND;
        }
      }
    }
  }
}

function makeGlow(rgb) {
  const c = document.createElement('canvas');
  c.width = c.height = 96;
  const g = c.getContext('2d');
  const grd = g.createRadialGradient(48, 48, 2, 48, 48, 48);
  grd.addColorStop(0, `rgba(${rgb},0.75)`);
  grd.addColorStop(0.45, `rgba(${rgb},0.3)`);
  grd.addColorStop(1, `rgba(${rgb},0)`);
  g.fillStyle = grd;
  g.fillRect(0, 0, 96, 96);
  return c;
}

// Recompute walkability and the minimap from the terrain.
function rebuildBlocked() {
  for (let i = 0; i < GW * GH; i++) {
    const t = terrain[i];
    blocked[i] = t === T_LAND || t === T_BRIDGE ? 0 : t === T_WATER ? 1 : t === T_FOREST ? 3 : 2;
  }
  L.mmCanvas = document.createElement('canvas');
  L.mmCanvas.width = GW; L.mmCanvas.height = GH;
  const m = L.mmCanvas.getContext('2d'), mi = m.createImageData(GW, GH);
  for (let i = 0; i < GW * GH; i++) {
    const t = terrain[i];
    let c;
    if (t === T_SEA) c = [110, 168, 220];
    else if (t === T_WATER) c = [60, 128, 190];
    else if (t === T_BRIDGE) c = [150, 100, 55];
    else if (t === T_BUILD) c = [170, 110, 90];
    else if (t === T_FOREST || t === T_EDGE) c = L.R.color.map(v => Math.round(v * 0.55));
    else if (swamp[i]) c = [104, 112, 62];
    else if (sandy[i]) c = [232, 214, 160];
    else c = L.R.color;
    mi.data.set([c[0], c[1], c[2], 255], i * 4);
  }
  m.putImageData(mi, 0, 0);
}

// ---------- Pathfinding ----------
const gCost = new Float32Array(GW * GH);
const came = new Int32Array(GW * GH);
const stamp = new Uint32Array(GW * GH);
const closedStamp = new Uint32Array(GW * GH);
let stampId = 0;

function walkCell(i, mode) {
  const b = blocked[i];
  if (b === 0) return true;
  if (!mode) return false;
  return mode === 'swim' ? b === 1 : b === 1 || b === 3;
}

function nearestWalkableCell(i, fly, maxR) {
  if (i >= 0 && walkCell(i, fly)) return i;
  if (i < 0) return -1;
  const cx = i % GW, cy = Math.floor(i / GW);
  for (let r = 1; r <= maxR; r++) {
    let best = -1, bd = Infinity;
    for (let dy = -r; dy <= r; dy++) {
      for (let dx = -r; dx <= r; dx++) {
        if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
        const x = cx + dx, y = cy + dy;
        if (x < 0 || y < 0 || x >= GW || y >= GH) continue;
        const j = y * GW + x;
        if (walkCell(j, fly) && dx * dx + dy * dy < bd) { bd = dx * dx + dy * dy; best = j; }
      }
    }
    if (best >= 0) return best;
  }
  return -1;
}

function findPath(sx, sy, tx, ty, fly) {
  const s = nearestWalkableCell(cellOf(sx, sy), fly, 3);
  const goal = nearestWalkableCell(cellOf(tx, ty), fly, 8);
  if (s < 0 || goal < 0) return null;
  stampId++;
  const heap = [];
  const gx = goal % GW, gy = Math.floor(goal / GW);
  const hfn = i => {
    const dx = Math.abs(i % GW - gx), dy = Math.abs(Math.floor(i / GW) - gy);
    return (dx + dy) + (Math.SQRT2 - 2) * Math.min(dx, dy);
  };
  const push = (f, i) => {
    heap.push([f, i]);
    let k = heap.length - 1;
    while (k > 0) {
      const p = (k - 1) >> 1;
      if (heap[p][0] <= heap[k][0]) break;
      [heap[p], heap[k]] = [heap[k], heap[p]];
      k = p;
    }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let k = 0;
      for (;;) {
        const l = 2 * k + 1, r = l + 1;
        let m = k;
        if (l < heap.length && heap[l][0] < heap[m][0]) m = l;
        if (r < heap.length && heap[r][0] < heap[m][0]) m = r;
        if (m === k) break;
        [heap[m], heap[k]] = [heap[k], heap[m]];
        k = m;
      }
    }
    return top;
  };
  stamp[s] = stampId; gCost[s] = 0; came[s] = -1;
  push(hfn(s), s);
  let iter = 0;
  while (heap.length && iter++ < 80000) {
    const [, cur] = pop();
    if (closedStamp[cur] === stampId) continue;
    closedStamp[cur] = stampId;
    if (cur === goal) break;
    const cx = cur % GW, cy = Math.floor(cur / GW);
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (!dx && !dy) continue;
        const x = cx + dx, y = cy + dy;
        if (x < 0 || y < 0 || x >= GW || y >= GH) continue;
        const n = y * GW + x;
        if (!walkCell(n, fly) || closedStamp[n] === stampId) continue;
        if (dx && dy && (!walkCell(cy * GW + x, fly) || !walkCell(y * GW + cx, fly))) continue;
        const ng = gCost[cur] + (dx && dy ? Math.SQRT2 : 1) * (swamp[n] ? 2 : 1);
        if (stamp[n] !== stampId || ng < gCost[n]) {
          stamp[n] = stampId; gCost[n] = ng; came[n] = cur;
          push(ng + hfn(n), n);
        }
      }
    }
  }
  if (closedStamp[goal] !== stampId) return null;
  const cells = [];
  for (let c = goal; c >= 0; c = came[c]) cells.push({ x: (c % GW + 0.5) * CELL, y: (Math.floor(c / GW) + 0.5) * CELL });
  cells.reverse();
  return cells;
}

function lineWalkable(a, b, fly) {
  const d = dist(a.x, a.y, b.x, b.y), n = Math.ceil(d / 10);
  for (let k = 1; k <= n; k++) if (!walkable(lerp(a.x, b.x, k / n), lerp(a.y, b.y, k / n), fly)) return false;
  return true;
}

function smoothRoute(start, pts, fly) {
  const all = [start, ...pts];
  const out = [];
  let i = 0;
  while (i < all.length - 1) {
    let j = Math.min(all.length - 1, i + 60);
    while (j > i + 1 && !lineWalkable(all[i], all[j], fly)) j--;
    out.push(all[j]);
    i = j;
  }
  return out;
}

// ---------- Audio ----------
let actx = null, muted = false;
function ensureAudio() {
  if (actx) return;
  try { actx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { actx = null; }
}
function tone(freq, freq2, dur, type, vol, delay = 0) {
  if (!actx || muted) return;
  const t0 = actx.currentTime + delay;
  const o = actx.createOscillator(), g = actx.createGain();
  o.type = type;
  o.frequency.setValueAtTime(freq, t0);
  o.frequency.exponentialRampToValueAtTime(freq2, t0 + dur);
  g.gain.setValueAtTime(vol, t0);
  g.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
  o.connect(g).connect(actx.destination);
  o.start(t0); o.stop(t0 + dur + 0.02);
}
function sfx(kind, n = 0) {
  if (kind === 'pling') tone(880 * (1 + Math.min(n, 8) * 0.06), 1400, 0.12, 'sine', 0.12);
  else if (kind === 'boing') { tone(320, 110, 0.28, 'triangle', 0.22); }
  else if (kind === 'win') { tone(520, 780, 0.1, 'square', 0.06); tone(780, 1040, 0.14, 'square', 0.06, 0.08); }
  else if (kind === 'chest') [523, 659, 784, 1046].forEach((f, k) => tone(f, f * 1.01, 0.16, 'triangle', 0.13, k * 0.07));
  else if (kind === 'fanfare') [392, 523, 659, 784, 659, 784, 1046].forEach((f, k) => tone(f, f, 0.22, 'square', 0.06, k * 0.13));
  else if (kind === 'sleep') tone(600, 200, 0.6, 'sine', 0.12);
  else if (kind === 'song') [587, 659, 784, 659, 587, 523, 587].forEach((f, k) => tone(f, f, 0.2, 'triangle', 0.09, k * 0.17));
}

// ---------- Save ----------
const SAVE_KEY = 'lacplesis-v4';
function loadSave() {
  try {
    const s = JSON.parse(localStorage.getItem(SAVE_KEY));
    if (s && typeof s.power === 'number' && Array.isArray(s.beaten) && Array.isArray(s.opened)) return s;
  } catch (e) { /* no save */ }
  return null;
}
function writeSave() {
  if (!game) return;
  const p = game.progress;
  const s = { power: Math.floor(game.hero.power), maxPower: Math.floor(game.hero.maxPower), loc: game.loc.id,
    beaten: [...p.beaten], opened: [...p.opened], jods: game.jods };
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(s)); } catch (e) { /* storage unavailable */ }
  game.dirty = false;
}
function clearSave() { try { localStorage.removeItem(SAVE_KEY); } catch (e) { /* ignore */ } }

